import{_ as o,a0 as u,w as l,s as p,I as r,x as t,a1 as a,A as n,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"Kubernetes 為什麼這麼重要？ | LCTT x X-CMD","titleTemplate":false,"description":"Kubernetes 為什麼這麼重要？ | LCTT (201709) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Kubernetes 為什麼這麼重要？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Kubernetes 為什麼這麼重要？ | LCTT (201709) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201709/20170629 Kubernetes Why does it matter","title":"Kubernetes 為什麼這麼重要？","tag":"201709","desc":""},"relativePath":"201709/20170629 Kubernetes Why does it matter.md","filePath":"[post].md"}'),b={name:"201709/20170629 Kubernetes Why does it matter.md"};function d(m,e,f,K,S,T){const s=u("Link");return l(),p("div",null,[e[20]||(e[20]=r("h1",{id:"kubernetes-為什麼這麼重要",tabindex:"-1"},[t("Kubernetes 為什麼這麼重要？ "),r("a",{class:"header-anchor",href:"#kubernetes-為什麼這麼重要","aria-label":"Permalink to “Kubernetes 為什麼這麼重要？”"},"​")],-1)),e[21]||(e[21]=r("blockquote",null,[r("p",null,"在開發和部署雲原生應用程序時，運行容器化負載的 Kubernetes 平台起到了重大作用。")],-1)),e[22]||(e[22]=r("p",null,[r("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/freesoftwareway_law3.png?itok=wyze_0fV",alt:"Kubernetes: Why does it matter?",title:"Kubernetes: Why does it matter?"})],-1)),e[23]||(e[23]=r("p",null,"自然而然的，開發和部署雲原生應用程序已經變得非常受歡迎。對於一個允許快速部署和連續交付的 bug 修復和新功能的流程來説，它有明顯的優勢，但是沒有人會談到雞和雞蛋問題：怎樣才能達成這樣的目的呢？從頭開始構建基礎設施和開發流程來開發和維護雲原生應用程序是個不簡單的、耗時的任務。",-1)),r("p",null,[a(s,{href:"https://kubernetes.io/"},{default:n(()=>[...e[0]||(e[0]=[t("Kubernetes",-1)])]),_:1}),e[2]||(e[2]=t(" 是一個相對較新的運行容器化負載的平台，它解決了這些問題。它原本是 Google 內部的一個項目，Kubernetes 在 2015 年被捐贈給了",-1)),a(s,{href:"https://www.cncf.io/"},{default:n(()=>[...e[1]||(e[1]=[t("雲原生計算基金會",-1)])]),_:1}),e[3]||(e[3]=t("，並吸引了來自世界各地開源社區的開發人員。 Kubernetes 的設計基於 Google 15 年的在生產和開發環境運維的經驗。由於它是開源的，任何人都可以下載並使用它，並實現其帶來的優勢。",-1))]),e[24]||(e[24]=i('<p>那麼為什麼 Kubernetes 會有這麼大的驚喜呢？我認為它在像 OpenStack 這樣的基礎架構即服務（IaaS）和完整的平台即服務 （PaaS）的資源之間達到了最佳平衡，它的底層運行時實現完全由供應商控制。Kubernetes 提供了兩個優勢：對管理基礎設施的抽象，以及深入裸機進行故障排除的工具和功能。</p><h3 id="iaas-與-paas" tabindex="-1">IaaS 與 PaaS <a class="header-anchor" href="#iaas-與-paas" aria-label="Permalink to “IaaS 與 PaaS”">​</a></h3><p>OpenStack 被大多數人歸類為 IaaS 解決方案，其中物理資源池（如處理器、網絡和存儲）在不同用户之間分配和共享。它使用傳統的基於硬件的虛擬化實現用户之間的隔離。</p><p>OpenStack 的 REST API 允許使用代碼自動創建基礎架構，但是這就是問題所在。IaaS 產品輸出的也是基礎設施。其創建後，支持和管理那些更多的基礎設施的服務方式並不多。在一定程度上，OpenStack 生產的底層基礎架構（如服務器和 IP 地址）成為管理工作的重中之重。一個眾所周知的結果是虛擬機（VM）的無序蔓延，而同樣的情況也出現於網絡、加密密鑰和存儲卷方面。這樣，開發人員建立和維護應用程序的時間就更少了。</p><p>像其它基於集羣的解決方案一樣，Kubernetes 以單個服務器級別的方式運行，以實現水平縮放。它可以輕鬆添加新的服務器，並立即在新硬件上安排負載。類似地，當服務器沒有被有效利用或需要維護時，可以從集羣中刪除服務器。其它 Kubernetes 可以自動處理的其他任務是編排活動，如工作調度、健康監測和維護高可用性。</p><p>網絡是另一個可能難以在 IaaS 環境中可靠編排的領域。微服務之間通過 IP 地址通信可能是很棘手的。Kubernetes 實現了 IP 地址管理、負載均衡、服務發現和 DNS 名稱註冊，以在集羣內提供無痛、透明的網絡環境。</p><h3 id="專為部署而設計" tabindex="-1">專為部署而設計 <a class="header-anchor" href="#專為部署而設計" aria-label="Permalink to “專為部署而設計”">​</a></h3><p>一旦創建了運行應用程序的環境，部署就是一件小事了。可靠地部署一個應用程序是説起來容易做起來難的任務 —— 它並不是最簡單的。Kubernetes 相對其他環境的巨大優勢是，部署是一等公民。</p><p>使用一個單獨的 Kubernetes 命令列界面（CLI）的命令，可以描述應用程序並將其安裝在羣集上。Kubernetes 從初始部署、推出新版本以及（當一個關鍵功能出現問題時）進行回滾，實現了應用程序的整個生命週期。運行中的部署也可以暫停和恢復。擁有現成的、內置的工具和支持應用程序部署，而不用自己構建部署系統，這是不容小覷的優點。Kubernetes 用户既不必重新發明應用程序部署的輪子，也不會發現這是一項艱鉅的任務。</p><p>Kubernetes 還可以監控運行中的部署的狀態。雖然你可以在 IaaS 環境中像編寫部署過程一樣編寫這個功能，但這是一個非常困難的任務，而這樣的情況還比比皆是。</p><h3 id="專為-devops-而設計" tabindex="-1">專為 DevOps 而設計 <a class="header-anchor" href="#專為-devops-而設計" aria-label="Permalink to “專為 DevOps 而設計”">​</a></h3><p>隨着你在開發和部署 Kubernetes 應用程序方面獲得更多經驗，你將沿着與 Google 和其他前行者相同的路徑前行。你將發現有幾種 Kubernetes 功能對於多服務應用程序的有效開發和故障排除是非常重要的。</p><p>首先，Kubernetes 能夠通過日誌或 SSH（安全 shell）輕鬆檢查正在運行的服務的能力非常重要。通過一條命令列調用，管理員可以檢查在 Kubernetes 下運行的服務的日誌。這可能聽起來像一個簡單的任務，但在 IaaS 環境中，除非你已經做了一些工作，否則這並不容易。大型應用程序通常具有專門用於日誌收集和分析的硬件和人員。在Kubernetes 中的日誌可能不能替代完整功能的日誌和指標解決方案，但它足以提供基本的故障排除。</p><p>第二，Kubernetes 提供內置的密鑰管理。從頭開發過自己的部署系統的團隊知道的另一個問題是，將敏感數據（如密碼和 API 令牌）安全地部署到虛擬機上很困難。通過將密鑰管理變成一等公民，Kubernetes 可以避免你的團隊發明自己的不安全的、錯誤的密鑰分發系統或在部署腳本中硬編碼憑據。</p><p>最後，Kubernetes 有一些用於自動進行縮放、負載均衡和重新啓動應用程序的功能。同樣，這些功能是開發人員在使用 IaaS 或裸機時要自己編寫的。你的 Kubernetes 應用程序的縮放和運行狀況檢查在服務定義中進行聲明，而 Kubernetes 會確保正確數量的實例健康運行。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>IaaS 和 PaaS 系統之間的差異是巨大的，包括 PaaS 可以節省大量的開發和調試時間。作為一種 PaaS，Kubernetes 實現了強大而有效的功能，可幫助你開發、部署和調試雲原生應用程序。它的架構和設計代表了數十年的難得的經驗，而你的團隊能夠免費獲得該優勢。</p><p>（題圖：opensource.com）</p><hr><p>作者簡介：</p>',20)),r("p",null,[e[5]||(e[5]=t("Tim Potter - Tim 是 Hewlett Packard Enterprise 的高級軟件工程師。近二十年來，他一直致力於自由和開源軟件的開發工作，其中包括 Samba、Wireshark、OpenPegasus 和 Docker 等多個項目。Tim Blog在 ",-1)),a(s,{href:"https://elegantinfrastructure.com/"},{default:n(()=>[...e[4]||(e[4]=[t("https://elegantinfrastructure.com/",-1)])]),_:1}),e[6]||(e[6]=t(" ，關於 Docker、Kubernetes 和其他基礎設施相關主題。",-1))]),e[25]||(e[25]=r("hr",null,null,-1)),r("p",null,[e[8]||(e[8]=t("via: ",-1)),a(s,{href:"https://opensource.com/article/17/6/introducing-kubernetes"},{default:n(()=>[...e[7]||(e[7]=[t("https://opensource.com/article/17/6/introducing-kubernetes",-1)])]),_:1})]),r("p",null,[e[12]||(e[12]=t("作者：",-1)),a(s,{href:"https://opensource.com/users/tpot"},{default:n(()=>[...e[9]||(e[9]=[t("Tim Potter",-1)])]),_:1}),e[13]||(e[13]=t(" 譯者：",-1)),a(s,{href:"https://github.com/geekpi"},{default:n(()=>[...e[10]||(e[10]=[t("geekpi",-1)])]),_:1}),e[14]||(e[14]=t(" 校對：",-1)),a(s,{href:"https://github.com/wxy"},{default:n(()=>[...e[11]||(e[11]=[t("wxy",-1)])]),_:1})]),r("p",null,[e[17]||(e[17]=t("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[15]||(e[15]=[t("LCTT",-1)])]),_:1}),e[18]||(e[18]=t(" 原創編譯，",-1)),a(s,{href:"https://linux.cn/"},{default:n(()=>[...e[16]||(e[16]=[t("Linux中國",-1)])]),_:1}),e[19]||(e[19]=t(" 榮譽推出",-1))])])}const I=o(b,[["render",d]]);export{g as __pageData,I as default};
